# Read JSON input from stdin
$input_data = $input | ConvertFrom-Json

# Get current directory
$current_dir = $input_data.workspace.current_dir
if (-not $current_dir) {
    $current_dir = Get-Location | Select-Object -ExpandProperty Path
}

# Get directory name (basename)
$dir_name = Split-Path -Leaf $current_dir

# Get current time
$time = Get-Date -Format "HH:mm:ss"

# Get git branch if in a git repository
$git_branch = ""
if (Test-Path (Join-Path $current_dir ".git")) {
    try {
        $branch = git -C $current_dir branch --show-current 2>$null
        if ($branch) {
            $git_branch = " ($branch)"
        }
    } catch {
        # Git not available or not a git repo
    }
}

# Build status line
$status_line = "$env:USERNAME@$env:COMPUTERNAME $dir_name$git_branch $time"

Write-Output $status_line

{
  "statusLine": {
    "type": "command",
    "command": "powershell -NoProfile -Command \"$input_data = $input | ConvertFrom-Json; $current_dir = $input_data.workspace.current_dir; if (-not $current_dir) { $current_dir = Get-Location | Select-Object -ExpandProperty Path }; $dir_name = Split-Path -Leaf $current_dir; $time = Get-Date -Format 'HH:mm:ss'; $git_branch = ''; if (Test-Path (Join-Path $current_dir '.git')) { try { $branch = git -C $current_dir branch --show-current 2>$null; if ($branch) { $git_branch = ' (' + $branch + ')' } } catch { } }; Write-Output \\\"$env:USERNAME@$env:COMPUTERNAME $dir_name$git_branch $time\\\"\""
  }
}

