﻿// CHAT UI MODULE
(function() {
    let chatHistory = [];

    function createChatUI() {
        // Check if already exists
        if (document.getElementById('chatOverlay')) return;

        const overlay = document.createElement('div');
        overlay.id = 'chatOverlay';
        overlay.className = 'chat-overlay';

        overlay.innerHTML = `
            <div class="chat-window">
                <div class="chat-header">
                    <h2>💬 Chat mit Najika</h2>
                    <button class="chat-close" onclick="ChatUI.close()">×</button>
                </div>
                <div class="chat-messages" id="chatMessages">
                    <div class="chat-message assistant">
                        <div class="chat-avatar">N</div>
                        <div class="chat-bubble">
                            Hey! Ich bin Najika. Schreib mir was! 💜
                        </div>
                    </div>
                </div>
                <div class="chat-typing" id="chatTyping">
                    <div class="typing-dot"></div>
                    <div class="typing-dot"></div>
                    <div class="typing-dot"></div>
                </div>
                <div class="chat-input-area">
                    <input type="text" id="chatInput" placeholder="Schreib mir eine Nachricht..." autocomplete="off">
                    <button id="chatSendBtn">Senden</button>
                </div>
            </div>
        `;

        document.body.appendChild(overlay);

        // Event Listeners
        const input = document.getElementById('chatInput');
        const sendBtn = document.getElementById('chatSendBtn');

        sendBtn.onclick = () => sendMessage();
        input.addEventListener('keypress', (e) => {
            if (e.key === 'Enter') sendMessage();
        });

        // Close on overlay click
        overlay.addEventListener('click', (e) => {
            if (e.target === overlay) ChatUI.close();
        });

        console.log('✅ Chat UI created');
    }

    function open() {
        createChatUI();
        const overlay = document.getElementById('chatOverlay');
        if (overlay) {
            overlay.classList.add('active');
            document.getElementById('chatInput').focus();
        }
    }

    function close() {
        const overlay = document.getElementById('chatOverlay');
        if (overlay) {
            overlay.classList.remove('active');
        }
    }

    function addMessage(role, text) {
        const container = document.getElementById('chatMessages');
        if (!container) return;

        const messageDiv = document.createElement('div');
        messageDiv.className = `chat-message ${role}`;

        messageDiv.innerHTML = `
            <div class="chat-avatar">${role === 'user' ? 'K' : 'N'}</div>
            <div class="chat-bubble">${escapeHtml(text)}</div>
        `;

        container.appendChild(messageDiv);
        container.scrollTop = container.scrollHeight;

        // Save to history
        chatHistory.push({role, text, timestamp: new Date().toISOString()});
    }

    function showTyping() {
        const typing = document.getElementById('chatTyping');
        if (typing) typing.classList.add('active');
    }

    function hideTyping() {
        const typing = document.getElementById('chatTyping');
        if (typing) typing.classList.remove('active');
    }

    async function sendMessage() {
        const input = document.getElementById('chatInput');
        const sendBtn = document.getElementById('chatSendBtn');
        const text = input.value.trim();

        if (!text) return;

        // Disable input
        input.disabled = true;
        sendBtn.disabled = true;

        // Add user message
        addMessage('user', text);
        input.value = '';

        // Show typing
        showTyping();

        try {
            const response = await fetch('/api/chat', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({message: text})
            });

            const data = await response.json();

            hideTyping();

            // Add assistant response
            addMessage('assistant', data.response || 'Keine Antwort erhalten.');

        } catch (error) {
            hideTyping();
            addMessage('assistant', 'Fehler: ' + error.message);
        } finally {
            input.disabled = false;
            sendBtn.disabled = false;
            input.focus();
        }
    }

    function escapeHtml(text) {
        const div = document.createElement('div');
        div.textContent = text;
        return div.innerHTML;
    }

    function getHistory() {
        return chatHistory;
    }

    function clearHistory() {
        chatHistory = [];
