﻿// TOUCH CONTROLS MODULE
(function() {
    let joystick = null;
    let joystickActive = false;
    let joystickCenter = {x: 0, y: 0};
    let joystickPosition = {x: 0, y: 0};

    function init() {
        // Only on touch devices
        if (!('ontouchstart' in window)) {
            console.log('⏭️ Touch controls skipped (not a touch device)');
            return;
        }

        createJoystick();
        setupTouchControls();

        console.log('✅ Touch controls initialized');
    }

    function createJoystick() {
        const container = document.createElement('div');
        container.id = 'touchJoystick';
        container.style.cssText = `
            position: fixed;
            bottom: 100px;
            left: 30px;
            width: 120px;
            height: 120px;
            background: radial-gradient(circle, rgba(102, 126, 234, 0.3), rgba(102, 126, 234, 0.1));
            border: 3px solid rgba(102, 126, 234, 0.5);
            border-radius: 50%;
            display: none;
            z-index: 1000;
            touch-action: none;
        `;

        const stick = document.createElement('div');
        stick.id = 'touchStick';
        stick.style.cssText = `
            position: absolute;
            width: 50px;
            height: 50px;
            background: linear-gradient(135deg, #667eea, #764ba2);
            border-radius: 50%;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            box-shadow: 0 5px 20px rgba(102, 126, 234, 0.5);
        `;

        container.appendChild(stick);
        document.body.appendChild(container);

        joystick = {
            container,
            stick
        };
    }

    function setupTouchControls() {
        const scene = document.getElementById('scene');
        if (!scene) return;

        // Touch start
        scene.addEventListener('touchstart', (e) => {
            if (e.touches.length === 1) {
                const touch = e.touches[0];

                // Show joystick at touch position
                if (joystick) {
                    joystick.container.style.display = 'block';
                    joystick.container.style.left = (touch.clientX - 60) + 'px';
                    joystick.container.style.bottom = (window.innerHeight - touch.clientY - 60) + 'px';

                    joystickCenter = {
                        x: touch.clientX,
                        y: touch.clientY
                    };

                    joystickActive = true;
                }
            }
        });

        // Touch move
        scene.addEventListener('touchmove', (e) => {
            if (!joystickActive || e.touches.length !== 1) return;

            e.preventDefault();
            const touch = e.touches[0];

            // Calculate joystick position
            const dx = touch.clientX - joystickCenter.x;
            const dy = touch.clientY - joystickCenter.y;
            const distance = Math.sqrt(dx * dx + dy * dy);
            const maxDistance = 40;

            if (distance > maxDistance) {
                const angle = Math.atan2(dy, dx);
                joystickPosition.x = Math.cos(angle) * maxDistance;
                joystickPosition.y = Math.sin(angle) * maxDistance;
            } else {
                joystickPosition.x = dx;
                joystickPosition.y = dy;
            }

            // Update stick position
            if (joystick) {
                joystick.stick.style.transform = `translate(calc(-50% + ${joystickPosition.x}px), calc(-50% + ${joystickPosition.y}px))`;
            }

            // Apply camera movement
            updateCamera();
        }, {passive: false});

        // Touch end
        scene.addEventListener('touchend', () => {
            if (joystick) {
                joystick.container.style.display = 'none';
                joystick.stick.style.transform = 'translate(-50%, -50%)';
            }

            joystickActive = false;
            joystickPosition = {x: 0, y: 0};
        });
    }

    function updateCamera() {
        if (!window.Scene3D || !window.Scene3D.camera) return;

        const camera = window.Scene3D.camera;
        const sensitivity = 0.02;

        // Rotate camera based on joystick
        const rotateX = -joystickPosition.y * sensitivity;
        const rotateY = -joystickPosition.x * sensitivity;

        // Update camera position
        const radius = 10;
        const currentAngle = Math.atan2(camera.position.z, camera.position.x);
        const newAngle = currentAngle + rotateY;

        camera.position.x = Math.cos(newAngle) * radius;
        camera.position.z = Math.sin(newAngle) * radius;
        camera.position.y = Math.max(3, Math.min(8, camera.position.y - rotateX));

        camera.lookAt(0, 2, 0);
    }

    // Pinch to zoom
    let lastTouchDistance = 0;

    document.addEventListener('touchstart', (e) => {
        if (e.touches.length === 2) {
            const touch1 = e.touches[0];
            const touch2 = e.touches[1];
            lastTouchDistance = Math.hypot(
                touch2.clientX - touch1.clientX,
                touch2.clientY - touch1.clientY
            );
        }
    });

    document.addEventListener('touchmove', (e) => {
        if (e.touches.length === 2 && window.Scene3D && window.Scene3D.camera) {
            const touch1 = e.touches[0];
            const touch2 = e.touches[1];
            const distance = Math.hypot(
                touch2.clientX - touch1.clientX,
                touch2.clientY - touch1.clientY
            );

            if (lastTouchDistance > 0) {
                const delta = distance - lastTouchDistance;
                const camera = window.Scene3D.camera;
                const currentRadius = Math.sqrt(
                    camera.position.x ** 2 + 
                    camera.position.z ** 2
                );
                const newRadius = Math.max(5, Math.min(20, currentRadius - delta * 0.05));
                const angle = Math.atan2(camera.position.z, camera.position.x);

                camera.position.x = Math.cos(angle) * newRadius;
                camera.position.z = Math.sin(angle) * newRadius;
            }

            lastTouchDistance = distance;
        }
    });

    // Export camera reference to Scene3D
    if (window.Scene3D) {
        const originalInit = window.Scene3D.init;
        window.Scene3D.init = function() {
            originalInit();
            // Store camera reference
            window.Scene3D.camera = window.Scene3D.camera || camera;
        };
    }

    // Auto-init
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }

    window.TouchControls = {
        enabled: true
    };
})();

