                assetsNeeded.add(prop.model);
            }
        });
    }

    if (assetsNeeded.size === 0) {
        console.log(`✅ Room "${roomName}" already loaded`);
        return;
    }

    console.log(`📦 Lazy loading room "${roomName}": ${assetsNeeded.size} new assets`);
    assetsNeeded.forEach(path => preloadAsset(path));
}

window.KayKitLoader = {
    init,
