// PERFORMANCE: Material & Texture Cache für Instancing
const materialCache = new Map();
const geometryCache = new Map();

function cloneObject(object) {
    if (THREE.SkeletonUtils && typeof THREE.SkeletonUtils.clone === 'function') {
        return THREE.SkeletonUtils.clone(object);
    }

    // PERFORMANCE: Instancing statt Deep Clone
    // Geometries & Materials werden geteilt, nur Transform wird geklont
    return cloneObjectWithInstancing(object);
}

function cloneObjectWithInstancing(object) {
    const clone = new THREE.Group();

    object.traverse(node => {
        if (node.isMesh) {
            // Teile Geometry & Material zwischen Instanzen
            const mesh = new THREE.Mesh(node.geometry, node.material);
            mesh.castShadow = true;
            mesh.receiveShadow = true;

            // Kopiere Transform
            mesh.position.copy(node.position);
            mesh.rotation.copy(node.rotation);
            mesh.scale.copy(node.scale);
            mesh.name = node.name;

            clone.add(mesh);
        } else if (node.isGroup || node.isObject3D) {
            // Rekursiv für verschachtelte Groups
            const childClone = cloneObjectWithInstancing(node);
            childClone.position.copy(node.position);
            childClone.rotation.copy(node.rotation);
            childClone.scale.copy(node.scale);
            childClone.name = node.name;
            clone.add(childClone);
        }
    });

    return clone;
}

function cloneGroup(group) {
    // PERFORMANCE: Nutze Instancing auch für Groups
    return cloneObjectWithInstancing(group);
}

