function startAnimationLoop() {
    const loop = () => {
        animationHandle = requestAnimationFrame(loop);
        const delta = clock ? clock.getDelta() : 0.016;
        updateCharacter(delta);
        updateCamera();
        if (pendingRoomBuild) {
            buildRoom();
        }

        // PERFORMANCE: Frustum Culling für große Räume (Schwarze Mühle)
        if (roomGroup && currentRoomSpan > 30) {
            optimizeFrustumCulling();
        }

        renderer.render(scene, camera);
    };
    loop();
}

function optimizeFrustumCulling() {
    // Three.js macht Frustum Culling automatisch, aber wir helfen bei großen Räumen
    // Deaktiviere Props die sehr weit weg sind (> 60 units)
    if (!roomGroup || !characterGroup) return;

    const charPos = characterGroup.position;
    const distanceThreshold = 60;

    roomGroup.traverse(node => {
        if (node.isMesh && node.userData.isProp) {
            const distance = node.position.distanceTo(charPos);
            node.visible = distance < distanceThreshold;
        }
    });
}

