/* === COOKING GAME === */
function startCookingGame(content) {
    content.innerHTML = `
        <div class="cooking-game">
            <div class="cooking-track" id="cookingTrack">
                <div class="cooking-zone"></div>
                <div class="cooking-items" id="cookingItems"></div>
            </div>
            <div class="cooking-controls">
                <button id="sliceButton">🔪 Schneiden</button>
                <div class="cooking-status">❤️ <span id="cookingLives">3</span></div>
            </div>
        </div>
    `;
    const track = document.getElementById('cookingTrack');
    const itemsContainer = document.getElementById('cookingItems');
    const sliceBtn = document.getElementById('sliceButton');
    const livesEl = document.getElementById('cookingLives');
    const items = [];
    const icons = ['🍅', '🥕', '🍄', '🥔', '🥦', '🧄', '🌶️'];
    let lives = 3;
    function updateLives() {
        livesEl.textContent = lives;
    }
    function spawnIngredient() {
        const el = document.createElement('div');
        el.className = 'cooking-item';
        el.textContent = icons[Math.floor(Math.random() * icons.length)];
        itemsContainer.appendChild(el);
        items.push({ el, x: -40, speed: 2.5 + Math.random() * 1.5 });
    }
    function loop() {
        frameHandle = requestAnimationFrame(loop);
        const trackWidth = track.clientWidth;
        const zoneStart = trackWidth / 2 - 50;
        const zoneEnd = trackWidth / 2 + 50;
        for (let i = items.length - 1; i >= 0; i--) {
            const item = items[i];
            item.x += item.speed;
            item.el.style.transform = `translateX(${item.x}px)`;
            if (item.x > trackWidth + 60) {
                item.el.remove();
                items.splice(i, 1);
                lives -= 1;
                updateLives();
                if (lives <= 0) {
                    itemsContainer.innerHTML = '<div class="cooking-message">Das Gericht ist verbrannt!</div>';
                    scheduleTimeout(() => close(), 1000);
                    return;
                }
            }
        }
    }
    sliceBtn.onclick = () => {
        const trackWidth = track.clientWidth;
        const zoneStart = trackWidth / 2 - 60;
        const zoneEnd = trackWidth / 2 + 60;
        const target = items.find(item => item.x >= zoneStart && item.x <= zoneEnd);
        if (target) {
            updateScore(9);
            target.el.classList.add('sliced');
            scheduleTimeout(() => target.el.remove(), 120);
            items.splice(items.indexOf(target), 1);
        } else {
            lives -= 1;
            updateLives();
            if (lives <= 0) {
                itemsContainer.innerHTML = '<div class="cooking-message">Das Messer verfehlt alles!</div>';
                scheduleTimeout(() => close(), 1000);
            }
        }
    };
    setCleanup(() => (sliceBtn.onclick = null));
    spawnIngredient();
    frameHandle = requestAnimationFrame(loop);
    gameInterval = setInterval(spawnIngredient, 1100);
    updateLives();
}

