﻿/* MINIGAME OVERLAY */
.minigame-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.95);
    backdrop-filter: blur(10px);
    z-index: 10000;
    display: none;
    align-items: center;
    justify-content: center;
    animation: fadeIn 0.3s ease;
}

.minigame-overlay.active {
    display: flex;
}

.minigame-container {
    width: 90%;
    max-width: 800px;
    height: 80vh;
    background: linear-gradient(135deg, #1a1a2e, #16213e);
    border-radius: 20px;
    border: 3px solid #667eea;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
}

.minigame-header {
    padding: 1rem 1.5rem;
    background: linear-gradient(135deg, #667eea, #764ba2);
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.minigame-header h2 {
    font-size: 1.3rem;
    margin: 0;
}

.minigame-score {
    font-size: 1.5rem;
    font-weight: bold;
}

.minigame-close {
    background: rgba(255, 255, 255, 0.2);

input.old_string:
.reflex-instruction {
    font-size: 1.2rem;
    opacity: 0.8;
}

input.new_string:
.reflex-instruction {
    font-size: 1.2rem;
    opacity: 0.8;
}

/* COOKING GAME NINJA STYLE */
.cooking-game-ninja {
    display: flex;
    flex-direction: column;
    gap: 1rem;
    height: 100%;
    padding: 1.5rem;
}

.cooking-recipe-display {
    background: rgba(0, 0, 0, 0.4);
    padding: 1rem;
    border-radius: 12px;
    text-align: center;
}

.cooking-recipe-display h4 {
    margin: 0 0 0.75rem;
    font-size: 1.2rem;
}

.recipe-ingredients {
    display: flex;
    gap: 0.75rem;
    justify-content: center;
    flex-wrap: wrap;
}

.recipe-ingredient {
    font-size: 2.5rem;
    padding: 0.5rem;
    background: rgba(255, 255, 255, 0.1);
    border-radius: 8px;
    opacity: 0.4;
    transition: all 0.3s;
}

.recipe-ingredient.collected {
    opacity: 1;
    background: linear-gradient(135deg, #2ecc71, #27ae60);
    box-shadow: 0 0 20px rgba(46, 204, 113, 0.6);
    animation: collectPulse 0.5s ease;
}

@keyframes collectPulse {
    0%, 100% { transform: scale(1); }
    50% { transform: scale(1.2); }
}

#cookingCanvas {
    flex: 1;
    border-radius: 12px;
    background: linear-gradient(135deg, #0f0f1a, #1a0f1e);
    cursor: crosshair;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
}

.cooking-hud {
    display: flex;
    justify-content: space-between;
    font-weight: 600;
    font-size: 1.1rem;
    padding: 0 0.5rem;
}

