    const DUNGEON_PROPS = {
        obstacles: [
            'KayKit_HalloweenBits_1.0_FREE/.../coffin.gltf',
            'KayKit_DungeonRemastered_1.1_FREE/.../crate_small_A.gltf',
            // ... more obstacles
