            'KayKit_Adventurers_1.0_FREE/.../potion_simple_red.gltf'
        ]
    };

    let seed = Date.now();

    // Seeded Random (LCG)
    function seededRandom() {
        seed = (seed * 1664525 + 1013904223) % 4294967296;
        return seed / 4294967296;
    }

    function generateDungeon(level = 1, span = 48, seedString = null) {
        if (seedString) {
            seed = hashString(seedString);
        } else {
            seed = Date.now() + level * 1000;
        }

        const difficulty = Math.min(level / 10, 1);
        const propCount = Math.floor(10 + difficulty * 20); // 10-30
        const enemyCount = Math.floor(3 + difficulty * 10); // 3-13
        const lootCount = Math.floor(2 + difficulty * 5); // 2-7

        const grid = createGrid(span, 4);
        const dungeon = {
            level,
            span,
            seed,
            props: [],
            enemies: [],
            loot: [],
            spawn: [0, 0, span * 0.3]
        };

        // Generate props with grid-based placement
        for (let i = 0; i < propCount; i++) {
            const isObstacle = seededRandom() > 0.3;
            const propList = isObstacle ? DUNGEON_PROPS.obstacles : DUNGEON_PROPS.decorations;
            const model = pickRandom(propList);

            const pos = getRandomGridPosition(grid, span, 4);
            if (!pos) continue;

            dungeon.props.push({
                model,
                position: [pos.x, 0, pos.z],
                rotation: [0, randomFloat(0, Math.PI * 2), 0],
                scale: randomFloat(1.4, 2.4)
            });
        }

        // Generate enemies and loot similarly...

        return dungeon;
    }

    window.DungeonGenerator = {
        generateDungeon,
        applyDungeonToRoom,
        regenerateDungeon,
        setDungeonLevel(level) {
            this.currentLevel = Math.max(1, Math.min(10, level));
        },
        currentLevel: 1
    };
})();
